     * does not define an identifier for the Pax calendar, but were it to
     * do so, 'pax' is highly likely to be chosen.
     *
     * @return the calendar system type - 'pax'
     * @see #getId()
     */
    @Override
    public String getCalendarType() {
        return "pax";
    }

